package com.adc.infrastructure;

import com.adc.domain.performance.QuarterlyCalculation.*;
import com.adc.domain.shared.DomainFailure;
import java.sql.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import tools.jackson.databind.json.JsonMapper;

@Repository
public class QuarterlyPerformanceStore {
    private final JdbcTemplate db;private static final JsonMapper JSON=JsonMapper.builder().build();
    public QuarterlyPerformanceStore(JdbcTemplate db){this.db=db;}
    public record Row(long id,long dentist,String start,String end,int version,String status,String hash,String snapshot,String revenue,String medical,String operating,String profit,String incentive,String published){}
    private static String decimal(ResultSet r,String name)throws SQLException{var value=r.getBigDecimal(name);return value==null?null:value.setScale(2).toPlainString();}
    private Row row(ResultSet r,int n)throws SQLException{var published=r.getObject("published_at",LocalDateTime.class);return new Row(r.getLong("quarterly_performance_id"),r.getLong("dentist_id"),r.getString("quarter_start"),r.getString("quarter_end"),r.getInt("calculation_version"),r.getString("calculation_status"),r.getString("input_hash"),r.getString("source_snapshot"),decimal(r,"revenue"),decimal(r,"medical_supply_cost"),decimal(r,"operating_expense"),decimal(r,"net_profit"),decimal(r,"incentive_amount"),published==null?null:published.toInstant(ZoneOffset.UTC).toString());}
    public List<Row> quarter(String start,String end){return db.query("SELECT * FROM adc_business.QuarterlyPerformance WHERE quarter_start=? AND quarter_end=? ORDER BY dentist_id,calculation_version",this::row,start,end);}
    public List<Row> all(){return db.query("SELECT * FROM adc_business.QuarterlyPerformance ORDER BY quarterly_performance_id",this::row);}
    public Row get(long id,boolean lock){var rows=db.query("SELECT * FROM adc_business.QuarterlyPerformance WHERE quarterly_performance_id=?"+(lock?" FOR UPDATE":""),this::row,id);if(rows.isEmpty())throw new DomainFailure(404,"OBJECT_NOT_ACCESSIBLE");return rows.getFirst();}
    public List<Long> allClinics(){return db.query("SELECT clinic_id FROM adc_business.Clinic ORDER BY clinic_id",(r,n)->r.getLong(1));}
    public Input capture(String start,String end,String cutoff,List<Long> clinics,List<Closure> closures,String reference,String preparer){
        var begin=LocalDate.parse(start).atStartOfDay(ZoneId.of("Asia/Shanghai")).withZoneSameInstant(ZoneOffset.UTC).toLocalDateTime();var until=LocalDate.parse(end).atStartOfDay(ZoneId.of("Asia/Shanghai")).withZoneSameInstant(ZoneOffset.UTC).toLocalDateTime();var freeze=LocalDateTime.ofInstant(Instant.parse(cutoff),ZoneOffset.UTC);
        if(db.queryForObject("SELECT COUNT(*) FROM adc_audit.AuditEvent WHERE occurred_at>? AND result='SUCCESS' AND action IN ('updateDentist','maintainDentistAssignment','suspendSchedule','updateClinic')",Integer.class,freeze)>0)throw new DomainFailure(422,"CUTOFF_NOT_REPRODUCIBLE");
        if(db.queryForObject("SELECT COUNT(*) FROM adc_business.Invoice v WHERE v.issued_at>=? AND v.issued_at<? AND v.created_at<=? AND NOT EXISTS(SELECT 1 FROM adc_business.InvoiceItem i WHERE i.invoice_id=v.invoice_id)",Integer.class,begin,until,freeze)>0)throw new DomainFailure(422,"INVALID_INVOICE_SOURCE");
        var revenue=db.query("SELECT i.invoice_item_id,i.invoice_id,i.applied_treatment_id,t.dentist_id,a.clinic_id,v.issued_at,i.subtotal,(t.appointment_id=v.appointment_id AND a.appointment_id=v.appointment_id AND i.subtotal=ROUND(i.standard_units*i.unit_price,2) AND v.total_amount=(SELECT SUM(x.subtotal) FROM adc_business.InvoiceItem x WHERE x.invoice_id=v.invoice_id)) AS consistent FROM adc_business.InvoiceItem i JOIN adc_business.Invoice v ON v.invoice_id=i.invoice_id JOIN adc_business.AppliedTreatment t ON t.applied_treatment_id=i.applied_treatment_id JOIN adc_business.Appointment a ON a.appointment_id=t.appointment_id WHERE v.issued_at>=? AND v.issued_at<? AND v.created_at<=? ORDER BY i.invoice_item_id",(r,n)->new Revenue(r.getLong(1),r.getLong(2),r.getLong(3),r.getLong(4),r.getLong(5),r.getObject(6,LocalDateTime.class).toInstant(ZoneOffset.UTC).toString(),r.getBigDecimal(7).setScale(2).toPlainString(),r.getBoolean(8)),begin,until,freeze);
        var costs=db.query("SELECT c.*,((c.appointment_id IS NULL OR EXISTS(SELECT 1 FROM adc_business.Appointment a WHERE a.appointment_id=c.appointment_id AND a.clinic_id=c.clinic_id)) AND (c.applied_treatment_id IS NULL OR EXISTS(SELECT 1 FROM adc_business.AppliedTreatment t JOIN adc_business.Appointment a ON a.appointment_id=t.appointment_id WHERE t.applied_treatment_id=c.applied_treatment_id AND t.dentist_id=c.dentist_id AND a.clinic_id=c.clinic_id AND (c.appointment_id IS NULL OR c.appointment_id=t.appointment_id))) AND (c.reversal_of_id IS NULL OR EXISTS(SELECT 1 FROM adc_business.CostEntry o WHERE o.cost_entry_id=c.reversal_of_id AND o.amount>0 AND c.amount=-o.amount AND c.cost_type=o.cost_type AND c.clinic_id=o.clinic_id AND c.dentist_id<=>o.dentist_id AND c.appointment_id<=>o.appointment_id AND c.applied_treatment_id<=>o.applied_treatment_id))) AS consistent FROM adc_business.CostEntry c WHERE c.incurred_at>=? AND c.incurred_at<? AND c.confirmed_at<=? ORDER BY c.cost_entry_id",(r,n)->new Cost(r.getLong("cost_entry_id"),(Long)r.getObject("dentist_id"),r.getLong("clinic_id"),r.getString("cost_type"),r.getBigDecimal("amount").setScale(2).toPlainString(),r.getObject("incurred_at",LocalDateTime.class).toInstant(ZoneOffset.UTC).toString(),r.getString("source_reference"),r.getString("source_batch"),r.getString("description"),(Long)r.getObject("reversal_of_id"),r.getBoolean("consistent")),begin,until,freeze);
        var included=new TreeSet<Long>();revenue.forEach(r->included.add(r.dentist()));costs.forEach(c->{if(c.dentist()!=null)included.add(c.dentist());});var people=db.query("SELECT dentist_id,hire_date,termination_date FROM adc_business.Dentist ORDER BY dentist_id",(r,n)->new Dentist(r.getLong(1),r.getString(2),r.getString(3))).stream().filter(d->(d.hire().compareTo(end)<0 && (d.termination()==null || d.termination().compareTo(start)>=0)) || included.contains(d.id())).toList();
        var assignments=db.query("SELECT assignment_id,dentist_id,clinic_id,start_date,end_date,is_active FROM adc_business.DentistClinicAssignment WHERE start_date<? AND (end_date IS NULL OR end_date>=?) ORDER BY assignment_id",(r,n)->new Assignment(r.getLong(1),r.getLong(2),r.getLong(3),r.getString(4),r.getString(5),r.getBoolean(6)),end,start).stream().filter(a->people.stream().anyMatch(d->d.id()==a.dentist())).toList();
        var schedules=db.query("SELECT schedule_id,dentist_id,clinic_id,schedule_date,start_time,end_time,schedule_status FROM adc_business.DentistSchedule WHERE schedule_date>=? AND schedule_date<? AND created_at<=? ORDER BY schedule_id",(r,n)->new Schedule(r.getLong(1),r.getLong(2),r.getLong(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7)),start,end,freeze).stream().filter(slot->people.stream().anyMatch(d->d.id()==slot.dentist())).toList();
        // clinic_ids is a selection hint, never a filter capable of dropping another clinic's sources.
        var required=new TreeSet<Long>(clinics);schedules.forEach(slot->required.add(slot.clinic()));revenue.forEach(r->required.add(r.clinic()));costs.forEach(c->required.add(c.clinic()));assignments.forEach(a->{if(people.stream().anyMatch(d->d.id()==a.dentist()))required.add(a.clinic());});return new Input("R1",start,end,cutoff,List.copyOf(required),people,assignments,schedules,revenue,costs,closures,reference,preparer);
    }
    public long save(long dentist,Input input,String hash,String snapshot,String status,Amounts amounts,Instant now){var existing=quarter(input.start(),input.end()).stream().filter(r->r.dentist==dentist && r.hash.equals(hash)).findFirst();if(existing.isPresent()){var row=existing.get();if(row.status.equals("DRAFT") && !status.equals("DRAFT")){db.update("UPDATE adc_business.QuarterlyPerformance SET revenue=?,medical_supply_cost=?,operating_expense=?,net_profit=?,incentive_amount=?,calculation_status=?,calculated_at=?,source_snapshot=? WHERE quarterly_performance_id=? AND calculation_status='DRAFT'",amounts.revenue(),amounts.medical(),amounts.operating(),amounts.profit(),amounts.incentive(),status,LocalDateTime.ofInstant(now,ZoneOffset.UTC),snapshot,row.id);}return row.id;}
        int version=quarter(input.start(),input.end()).stream().filter(r->r.dentist==dentist).mapToInt(Row::version).max().orElse(0)+1;long id=Crypto.id();db.update("INSERT INTO adc_business.QuarterlyPerformance VALUES (?,?,?,?,?,?,?,?,0.1000,?,?,?,?,?,?,NULL)",id,dentist,input.start(),input.end(),amounts.revenue(),amounts.medical(),amounts.operating(),amounts.profit(),amounts.incentive(),status,status.equals("DRAFT")?null:LocalDateTime.ofInstant(now,ZoneOffset.UTC),version,snapshot,hash);return id;
    }
    public Map<String,Object> view(Row row){var view=new LinkedHashMap<String,Object>();view.put("quarterly_performance_id",Long.toString(row.id));view.put("dentist_id",Long.toString(row.dentist));view.put("quarter_start",row.start);view.put("quarter_end",row.end);view.put("calculation_version",row.version);view.put("calculation_status",row.status);view.put("revenue",row.revenue);view.put("medical_supply_cost",row.medical);view.put("operating_expense",row.operating);view.put("net_profit",row.profit);view.put("incentive_rate","0.1000");view.put("incentive_amount",row.incentive);view.put("input_hash",row.hash);var reasons=JSON.readTree(row.snapshot).get("incomplete_reasons");view.put("incomplete_reasons",reasons==null?List.of():JSON.readValue(reasons.toString(),List.class));view.put("published_at",row.published);var frozen=JSON.readTree(row.snapshot).get("input");view.put("cutoff",frozen.get("cutoff").asText());view.put("clinic_ids",JSON.readValue(frozen.get("clinics").toString(),List.class).stream().map(String::valueOf).toList());return view;}
    public void publish(Row row,Instant now){db.query("SELECT quarterly_performance_id FROM adc_business.QuarterlyPerformance WHERE dentist_id=? AND quarter_start=? AND quarter_end=? ORDER BY calculation_version FOR UPDATE",(r,n)->r.getLong(1),row.dentist,row.start,row.end);db.update("UPDATE adc_business.QuarterlyPerformance SET calculation_status='SUPERSEDED' WHERE dentist_id=? AND quarter_start=? AND quarter_end=? AND calculation_status='PUBLISHED' AND quarterly_performance_id<>?",row.dentist,row.start,row.end,row.id);db.update("UPDATE adc_business.QuarterlyPerformance SET calculation_status='PUBLISHED',published_at=? WHERE quarterly_performance_id=? AND calculation_status='CALCULATED'",LocalDateTime.ofInstant(now,ZoneOffset.UTC),row.id);}
}
